      const refill = int(parts[3], 'refill', 0)
      const per = int(parts[4], 'per', 1)
      policies.set(name, { kind: 'bucket', name, cap, refill, per, states: new Map() })
    } else {
      const limit = int(parts[2], 'limit', 0)
      const span = int(parts[3], 'span', 1)
      policies.set(name, { kind: 'window', name, limit, span, states: new Map() })
    }
  } else if (w === 'route') {
    if (parts.length < 3) throw new Fail('expected route <prefix> <policy>...')
    const prefix = parts[1]
    if (!NAME.test(prefix)) throw new Fail(`invalid route prefix ${prefix}`)
    if (routes.has(prefix)) throw new Fail(`prefix ${prefix} is routed twice`)
    const list = parts.slice(2).map((n) => {
      if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
      return policies.get(n)
    })
    routes.set(prefix, list)
  } else {
    if (parts.length !== 3) throw new Fail('expected event <tick> <key>')
    const tick = int(parts[1], 'tick', 0)
    const key = parts[2]
    if (!NAME.test(key)) throw new Fail(`invalid key ${key}`)
    if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
    started = true
    lastTick = tick
    let best = null
    for (const pre of routes.keys()) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    let denied = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        if (!p.states.has(key)) p.states.set(key, p.kind === 'bucket' ? { num: 0n, last: null } : { ticks: [] })
        const st = p.states.get(key)
        advance(p, st, tick)
        return st
      })
      for (let i = 0; i < list.length; i++) if (!allows(list[i], sts[i])) { denied = list[i].name; break }
      if (denied === null) list.forEach((p, i) => record(p, sts[i], tick))
    }
    out.push(denied === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denied}`)
    const s = stats.get(key) || { a: 0, d: 0 }
    if (denied === null) s.a++; else s.d++
    stats.set(key, s)
  }
}

try {
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    try { handle(line.split(/\s+/)) } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}

if (mode === 'replay') {
  process.stdout.write(out.map((l) => l + '\n').join(''))
} else {
  let a = 0, d = 0
  let res = ''
  for (const k of [...stats.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    const s = stats.get(k)
    a += s.a; d += s.d
    res += `${k} allowed=${s.a} denied=${s.d}\n`
  }
  process.stdout.write(res + `total allowed=${a} denied=${d}\n`)
}
